def solve_priced_edits(text):
    tokens = text.split()
    ins, dele, sub = int(tokens[0]), int(tokens[1]), int(tokens[2])
    q = int(tokens[3])
    out = []
    for k in range(q):
        s, t = tokens[4 + 2 * k], tokens[5 + 2 * k]
        prev = [j * ins for j in range(len(t) + 1)]
        for i, x in enumerate(s, 1):
            cur = [i * dele]
            for j, y in enumerate(t, 1):
                best = prev[j - 1] + (0 if x == y else sub)
                if prev[j] + dele < best:
                    best = prev[j] + dele
                if cur[j - 1] + ins < best:
                    best = cur[j - 1] + ins
                cur.append(best)
            prev = cur
        out.append(str(prev[-1]))
    return '\n'.join(out)

